data['de']['cards']=[('Text mit Zeit und Sprecher','Zeitangaben und hervorgehobene Namen helfen, die passende Stelle in einer langen Vorlesung wiederzufinden.'),('Folien neben dem Transkript','Erklärung und Bildschirmfreigabe gemeinsam ansehen. Die Hauptfolie bleibt vollständig; Miniaturen erleichtern die Suche.'),('Pause, Stopp und Wiederherstellung','Die Erfassung unterbrechen, dieselbe Vorlesung fortsetzen oder beenden. Nach einem Absturz wird dieselbe Datei weitergeführt.')]
data['en']['cards']=[('Text with time and speaker','Find the relevant part: timestamps and highlighted names help you navigate a long lecture.'),('Slides beside the transcript','Compare the explanation with the shared material. The main slide stays complete; thumbnails help you find a moment.'),('Pause, finish and recover','Pause collection, resume the same lecture or finish it. After a crash, the previous file is retained.')]

for lang,title,body in [
    ('ru','Почему слайд виден, а сохранено — 0?','Галерея может показывать снимок, уже сохранённый сегодня. Программа использует прежний файл, чтобы не создавать повторную копию. Счётчик «Сохранено» учитывает только новые файлы текущей записи и начинается с нуля после перезапуска или нового старта. Счётчик дубликатов показывает пропущенные повторные изображения. Существующие файлы остаются в архиве.'),
    ('de','Warum ist eine Folie sichtbar, obwohl 0 gespeichert wurden?','Die Galerie kann ein Bild anzeigen, das heute bereits gespeichert wurde. Die App verwendet die vorhandene Datei, statt eine weitere Kopie anzulegen. „Gespeichert“ zählt nur neue Dateien der aktuellen Aufnahme und beginnt nach einem Neustart oder einer neuen Aufnahme bei null. Der Duplikatzähler zeigt übersprungene wiederholte Bilder. Vorhandene Dateien bleiben im Archiv.'),
    ('en','Why is a slide visible when the saved count is 0?','The gallery can show an image already saved today. The app reuses the existing file instead of creating another copy. The saved count includes only new files in the current recording and starts at zero after a restart or a new recording. The duplicate count shows repeated images that were skipped. Existing files remain in the archive.')
]:
    data[lang]['statsTitle']=title; data[lang]['statsBody']=body

for lang,label in {'ru':'Гибкие настройки','de':'Flexible Einstellungen','en':'Flexible settings'}.items(): data[lang]['tuneKicker']=label

def e(s): return html.escape(s)
def asset(path):
    file=SITE/path
    return path+'?v='+hashlib.sha256(file.read_bytes()).hexdigest()[:12] if file.is_file() else path
def header(lang,guide=False):
    d=data[lang]; stem='Guide' if guide else 'index'
    nav=''.join(f'<a href="{stem}-{l}.html" lang="{l}"'+(' aria-current="page"' if l==lang else '')+f'>{l.upper()}</a>' for l in languages)
    language_label={'ru':'Язык','de':'Sprache','en':'Language'}[lang]
    return f'<header class="shell top"><a class="brand" href="index-{lang}.html"><img src="assets/icon.png" alt="">SaveLecture</a><div class="links"><a href="Guide-{lang}.html">{d["guide"]}</a><div class="langs" aria-label="{language_label}">{nav}</div></div></header>'
def consent(lang):
    short={
        'ru':'Получите согласие всех участников и разрешение на материалы до сохранения. При отказе или отзыве остановите сбор.',
        'de':'Vor dem Speichern die Zustimmung aller Beteiligten und Erlaubnis für die Materialien einholen. Bei Ablehnung oder Widerruf die Erfassung stoppen.',
        'en':'Obtain every participant’s consent and permission for the materials before saving. Stop collecting if consent is refused or withdrawn.'
    }
    d=data[lang]; return f'<aside class="consent"><div class="shield" aria-hidden="true">i</div><div><h2>{d["consent"]}</h2><p>{short[lang]} <a href="Guide-{lang}.html#privacy">{d["learn"]} →</a></p></div></aside>'
def footer(lang):
    catalog='index.html' if lang=='en' else 'index-'+lang+'.html'
    help_url='https://github.com/popovantondev/SaveLecture/issues/new' if release['published'] else f'Guide-{lang}.html#trouble'
    d=data[lang]; return f'<footer><div class="shell footer-inner"><span>{d["footer"]}</span><div><a href="Guide-{lang}.html#rights">{d["rights"]}</a><a href="{help_url}">{d["help"]}</a><a href="https://popovantondev.github.io/popovantondev/{catalog}">popovantondev</a></div></div></footer>'
def page(lang,title,body,guide=False):
    return f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(data[lang]["lead"])}"><meta name="theme-color" content="#f4f8fd"><title>SaveLecture — {e(title)}</title><link rel="icon" href="assets/icon.png"><link rel="stylesheet" href="{asset("site.css")}"></head><body>{header(lang,guide)}{body}{footer(lang)}</body></html>'
def main():
    SITE.mkdir(exist_ok=True)
    for lang,d in data.items():
        cards=''.join(f'<article class="card"><span class="number">0{i+1}</span><h3>{e(t)}</h3><p>{e(b)}</p></article>' for i,(t,b) in enumerate(d['cards']))
        body=f'<main class="shell"><section class="hero"><div class="eyebrow">{d["purpose"]}</div><h1>{d["title"]}</h1><p class="lead">{d["lead"]}</p><div class="actions"><a class="button primary" href="Guide-{lang}.html">{d["guide"]} ↗</a><a class="button" href="https://github.com/popovantondev/SaveLecture">{d["source"]}</a></div><p class="note">{d["note"]}</p><div class="screen-wrap"><a href="{asset(f"assets/demo-{lang}.png")}"><img src="{asset(f"assets/demo-{lang}.png")}" width="1100" height="800" alt="SaveLecture — {d["caption"]}"></a><p class="caption">{d["caption"]}</p></div></section>{consent(lang)}<section class="section"><div class="kicker">{d["kicker"]}</div><h2>{d["features"]}</h2><div class="grid">{cards}</div></section><section class="section split"><div><div class="kicker">{d["tuneKicker"]}</div><h2>{d["tune"]}</h2><p>{d["tuneBody"]}</p><a class="button" href="Guide-{lang}.html#settings">{d["guide"]} →</a></div><a class="settings-shot" href="{asset(f"assets/filters-{lang}.png")}"><img src="{asset(f"assets/filters-{lang}.png")}" width="1100" height="800" alt="{d["settings"]}" loading="lazy"></a></section><section class="section"><h2 id="limits">{d["limits"]}</h2><div class="details"><p>{d["limitsBody"]}</p></div></section></main>'
        (SITE/f'index-{lang}.html').write_text(page(lang,d['status'],body),encoding='utf8')
        sections=[('steps',d['steps']),('settings',d['settings']),('storage',d['storage']),('startup',d['startup']),('privacy',d['privacyTitle']),('rights',d['rights']),('trouble',d['trouble']),('limits',d['limits'])]
        nav=''.join(f'<a href="#{a}">{e(t)}</a>' for a,t in sections)
        rows=''.join(f'<tr><th>{e(a)}</th><td>{e(b)}</td></tr>' for a,b in d['rows'])
        steps=''.join(f'<li>{e(s)}</li>' for s in d['stepList'])
        sources='<a href="https://www.edpb.europa.eu/sme/be-compliant/process-personal-data-lawfully_en">EDPB</a> · <a href="https://www.gesetze-im-internet.de/stgb/__201.html">§ 201 StGB</a>'
        contents_label={'ru':'Содержание','de':'Inhalt','en':'Contents'}[lang]
        guide_lead={
            'ru':'Первые шаги, настройки и ответы на вопросы — всё, что нужно для работы с SaveLecture.',
            'de':'Erste Schritte, Einstellungen und Antworten auf häufige Fragen — alles für den Einstieg mit SaveLecture.',
            'en':'First steps, settings and answers to common questions — everything you need to get started with SaveLecture.'
        }[lang]
        body=f'<main class="shell guide"><section class="section guide-intro"><div class="eyebrow">{d["status"]}</div><h1>{d["guide"]}</h1><p class="guide-lead">{guide_lead}</p><nav class="guide-nav" aria-label="{contents_label}">{nav}</nav></section>{consent(lang)}<section class="section guide-section"><h2 id="steps">{d["steps"]}</h2><div class="guide-steps"><ol>{steps}</ol><a class="settings-shot" href="{asset(f"assets/consent-{lang}.png")}"><img src="{asset(f"assets/consent-{lang}.png")}" width="660" height="510" alt="{d["consent"]}"></a></div></section><section class="section guide-section"><h2 id="settings">{d["settings"]}</h2><table class="settings-table">{rows}</table></section>'
        for anchor,title,text in [
            ('storage',d['storage'],d['storageBody']),('startup',d['startup'],d['startupBody']),
            ('privacy',d['privacyTitle'],d['privacyExtra']),('rights',d['rights'],d['rightsBody']),
            ('trouble',d['trouble'],d['troubleBody']),('limits',d['limits'],d['limitsBody'])
        ]:
            links=f'<p class="reference-links">{sources}</p>' if anchor=='privacy' else ''
            if anchor=='trouble': links+=f'<div class="guide-answer"><h3>{d["statsTitle"]}</h3><p>{d["statsBody"]}</p></div>'
            body+=f'<section class="section guide-section"><h2 id="{anchor}">{title}</h2><p>{text}</p>{links}</section>'
        body+='</main>'
        (SITE/f'Guide-{lang}.html').write_text(page(lang,d['guide'],body,True),encoding='utf8')
    (SITE/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=index-en.html"><title>SaveLecture</title><a href="index-en.html">SaveLecture</a></html>',encoding='utf8')
    (SITE/'content.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf8')

if __name__=='__main__': main()
